import axios from 'axios';

const API_BASE_URL = 'http://localhost:3001/api';

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// مسارات الملفات
export const fileApi = {
  upload: (file: File) => {
    const formData = new FormData();
    formData.append('file', file);
    return api.post('/files/upload', formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
    });
  },
  getUrl: (id: string) => `${API_BASE_URL}/files/${id}`,
};

// مسارات عامة CRUD
export function createCrudApi<T>(endpoint: string) {
  return {
    getAll: () => api.get(`/${endpoint}`),
    getById: (id: string) => api.get(`/${endpoint}/${id}`),
    create: (data: Partial<T>) => api.post(`/${endpoint}`, data),
    update: (id: string, data: Partial<T>) => api.put(`/${endpoint}/${id}`, data),
    delete: (id: string) => api.delete(`/${endpoint}/${id}`),
  };
}

export default api;

import { useState } from 'react';
import { Outlet, useNavigate, useLocation } from 'react-router-dom';
import { Layout as AntLayout, Menu, theme } from 'antd';
import logoFull from '/logo.svg';
import logoIcon from '/logo-icon.svg';
import {
  DashboardOutlined,
  TeamOutlined,
  FolderOpenOutlined,
  CalendarOutlined,
  NotificationOutlined,
  DollarOutlined,
  ShoppingCartOutlined,
  SettingOutlined,
  FileTextOutlined,
  UserOutlined,
  MenuFoldOutlined,
  MenuUnfoldOutlined,
} from '@ant-design/icons';

const { Header, Sider, Content } = AntLayout;

const menuItems = [
  { key: '/', icon: <DashboardOutlined />, label: 'لوحة التحكم' },
  { key: '/customers', icon: <TeamOutlined />, label: 'العملاء' },
  { key: '/cases', icon: <FolderOpenOutlined />, label: 'القضايا' },
  { key: '/sessions', icon: <CalendarOutlined />, label: 'الجلسات' },
  { key: '/announcements', icon: <NotificationOutlined />, label: 'الإعلانات' },
  { key: '/fees', icon: <DollarOutlined />, label: 'الرسوم' },
  { key: '/expenses', icon: <ShoppingCartOutlined />, label: 'المصاريف' },
  { key: '/templates', icon: <FileTextOutlined />, label: 'القوالب' },
  {
    key: 'settings',
    icon: <SettingOutlined />,
    label: 'الإعدادات',
    children: [
      { key: '/settings/courts', icon: <SettingOutlined />, label: 'المحاكم' },
      { key: '/settings/case-types', icon: <SettingOutlined />, label: 'أنواع القضايا' },
      { key: '/settings/announcement-types', icon: <SettingOutlined />, label: 'أنواع الإعلانات' },
      { key: '/settings/lawyer-profile', icon: <UserOutlined />, label: 'بيانات المحامي' },
    ],
  },
];

export function Layout() {
  const [collapsed, setCollapsed] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const { token } = theme.useToken();

  const selectedKey = location.pathname;
  const openKeys = selectedKey.startsWith('/settings') ? ['settings'] : [];

  return (
    <AntLayout style={{ minHeight: '100vh' }}>
      <Sider
        trigger={null}
        collapsible
        collapsed={collapsed}
        theme="light"
        style={{ borderLeft: `1px solid ${token.colorBorderSecondary}` }}
        width={240}
      >
        <div style={{
          height: 60,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          borderBottom: `1px solid ${token.colorBorderSecondary}`,
          padding: collapsed ? '4px' : '8px',
        }}>
          <img
            src={collapsed ? logoIcon : logoFull}
            alt="LEX PRO"
            style={{
              height: collapsed ? 36 : 40,
              objectFit: 'contain',
            }}
          />
        </div>
        <Menu
          mode="inline"
          selectedKeys={[selectedKey]}
          defaultOpenKeys={openKeys}
          items={menuItems}
          onClick={({ key }) => navigate(key)}
          style={{ borderInlineStart: 'none' }}
        />
      </Sider>
      <AntLayout>
        <Header style={{
          background: token.colorBgContainer,
          padding: '0 16px',
          display: 'flex',
          alignItems: 'center',
          borderBottom: `1px solid ${token.colorBorderSecondary}`,
        }}>
          <span
            onClick={() => setCollapsed(!collapsed)}
            style={{ fontSize: 18, cursor: 'pointer', marginLeft: 16 }}
          >
            {collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />}
          </span>
          <span style={{ fontSize: 16, fontWeight: 600 }}>
            {menuItems.find(m => m.key === selectedKey)?.label ||
             menuItems.flatMap(m => (m as any).children || []).find((c: any) => c.key === selectedKey)?.label ||
             'LEX PRO'}
          </span>
        </Header>
        <Content style={{ margin: 0, padding: 24, overflow: 'auto' }}>
          <Outlet />
        </Content>
      </AntLayout>
    </AntLayout>
  );
}

