import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { Table, Button, Modal, Form, Input, Select, Space, Popconfirm, message, Card, Typography, Row, Col } from 'antd';
import { PlusOutlined, EditOutlined, DeleteOutlined } from '@ant-design/icons';
import { createCrudApi } from '../api/client';

const { Title } = Typography;

const feesApi = createCrudApi('/fees');
const customersApi = createCrudApi('/customers');
const casesApi = createCrudApi('/cases');

export default function Fees() {
  const navigate = useNavigate();
  const [data, setData] = useState<any[]>([]);
  const [customers, setCustomers] = useState<any[]>([]);
  const [cases, setCases] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [form] = Form.useForm();
  const [submitting, setSubmitting] = useState(false);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const [feeRes, custRes, caseRes] = await Promise.all([feesApi.getAll(), customersApi.getAll(), casesApi.getAll()]);
      setData(feeRes.data.data || feeRes.data || []);
      setCustomers(custRes.data.data || custRes.data || []);
      setCases(caseRes.data.data || caseRes.data || []);
    } catch { message.error('حدث خطأ'); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { fetchData(); }, [fetchData]);

  const openModal = (record?: any) => {
    setEditing(record || null);
    if (record) form.setFieldsValue(record);
    else form.resetFields();
    setModalOpen(true);
  };

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      setSubmitting(true);
      if (editing?._id) await feesApi.update(editing._id, values);
      else await feesApi.create(values);
      message.success(editing ? 'تم التحديث' : 'تمت الإضافة');
      setModalOpen(false);
      fetchData();
    } catch (e: any) { if (!e?.errorFields) message.error('حدث خطأ'); }
    finally { setSubmitting(false); }
  };

  const handleDelete = async (id: string) => {
    try { await feesApi.delete(id); message.success('تم الحذف'); fetchData(); }
    catch { message.error('حدث خطأ'); }
  };

  const columns = [
    { title: 'العميل', dataIndex: 'customerName' },
    { title: 'رقم القضية', dataIndex: 'caseNumber' },
    { title: 'المبلغ الإجمالي', dataIndex: 'totalAmount' },
    { title: 'المدفوع', dataIndex: 'paidAmount', render: (v: string) => v || '0' },
    { title: 'المتبقي', dataIndex: 'remainingAmount', render: (v: string) => v || '0' },
    { title: 'التاريخ', dataIndex: 'agreementDate' },
    { title: 'إجراءات', render: (_: any, r: any) => (
      <Space>
        <Button type="text" icon={<EditOutlined />} onClick={(e) => { e.stopPropagation(); openModal(r); }} />
        <Popconfirm title="حذف؟" onConfirm={() => handleDelete(r._id)}><Button type="text" danger icon={<DeleteOutlined />} onClick={(e) => e.stopPropagation()} /></Popconfirm>
      </Space>
    )},
  ];

  return (
    <div>
      <Row justify="space-between" align="middle" style={{ marginBottom: 16 }}>
        <Col><Title level={3} style={{ margin: 0 }}>الرسوم</Title></Col>
        <Col><Button type="primary" icon={<PlusOutlined />} onClick={() => openModal()}>إضافة اتفاقية رسوم</Button></Col>
      </Row>
      <Card>
        <Table columns={columns} dataSource={data} rowKey="_id" loading={loading} onRow={(r) => ({ onClick: () => navigate(`/fees/${r._id}`), style: { cursor: 'pointer' } })} scroll={{ x: 800 }} />
      </Card>
      <Modal title={editing ? 'تعديل اتفاقية' : 'إضافة اتفاقية رسوم'} open={modalOpen} onOk={handleSubmit} onCancel={() => setModalOpen(false)} confirmLoading={submitting} okText="حفظ" cancelText="إلغاء" width={640} destroyOnClose>
        <Form form={form} layout="vertical">
          <Form.Item name="customerId" label="العميل" rules={[{ required: true }]}><Select showSearch optionFilterProp="children" options={customers.map((c: any) => ({ value: c._id, label: c.name }))} /></Form.Item>
          <Form.Item name="caseId" label="القضية"><Select showSearch allowClear optionFilterProp="children" options={cases.map((c: any) => ({ value: c._id, label: `${c.caseNumber}/${c.caseYear}` }))} /></Form.Item>
          <Row gutter={16}>
            <Col span={12}><Form.Item name="totalAmount" label="المبلغ الإجمالي" rules={[{ required: true }]}><Input type="number" /></Form.Item></Col>
            <Col span={12}><Form.Item name="agreementDate" label="تاريخ الاتفاقية" rules={[{ required: true }]}><Input type="date" /></Form.Item></Col>
          </Row>
          <Form.Item name="notes" label="ملاحظات" rules={[{ required: true }]}><Input.TextArea rows={2} /></Form.Item>
        </Form>
      </Modal>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Card, Descriptions, Table, Button, Modal, Form, Input, message, Spin, Typography, Row, Col, Space, Tag } from 'antd';
import { ArrowRightOutlined, PlusOutlined, EditOutlined } from '@ant-design/icons';
import { createCrudApi } from '../api/client';

const { Title } = Typography;

const feesApi = createCrudApi('/fees');
const paymentsApi = createCrudApi('/fee-payments');

export default function FeeDetail() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [feeData, setFeeData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [payModalOpen, setPayModalOpen] = useState(false);
  const [editModalOpen, setEditModalOpen] = useState(false);
  const [payForm] = Form.useForm();
  const [editForm] = Form.useForm();
  const [submitting, setSubmitting] = useState(false);

  const fetchData = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    try {
      const res = await feesApi.getById(id);
      setFeeData(res.data.data || res.data);
    } catch { message.error('حدث خطأ'); }
    finally { setLoading(false); }
  }, [id]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const handleAddPayment = async () => {
    try {
      const values = await payForm.validateFields();
      setSubmitting(true);
      await paymentsApi.create({ ...values, feeAgreementId: id });
      message.success('تم إضافة الدفعة');
      setPayModalOpen(false);
      payForm.resetFields();
      fetchData();
    } catch (e: any) { if (!e?.errorFields) message.error('حدث خطأ'); }
    finally { setSubmitting(false); }
  };

  const handleEditAmount = async () => {
    try {
      const values = await editForm.validateFields();
      setSubmitting(true);
      await feesApi.update(id!, { totalAmount: values.newTotalFee, reason: values.reason, changedBy: values.changedBy });
      message.success('تم تعديل المبلغ');
      setEditModalOpen(false);
      editForm.resetFields();
      fetchData();
    } catch (e: any) { if (!e?.errorFields) message.error('حدث خطأ'); }
    finally { setSubmitting(false); }
  };

  if (loading) return <Spin size="large" style={{ display: 'flex', justifyContent: 'center', marginTop: 100 }} />;
  if (!feeData) return <div>الاتفاقية غير موجودة</div>;

  const payments = feeData.payments || [];
  const history = feeData.history || [];

  const payColumns = [
    { title: 'المبلغ', dataIndex: 'amount' },
    { title: 'تاريخ الدفع', dataIndex: 'paymentDate' },
    { title: 'ملاحظات', dataIndex: 'notes' },
  ];

  const histColumns = [
    { title: 'المبلغ القديم', dataIndex: 'oldTotalFee' },
    { title: 'المبلغ الجديد', dataIndex: 'newTotalFee' },
    { title: 'السبب', dataIndex: 'reason' },
    { title: 'بواسطة', dataIndex: 'changedBy' },
    { title: 'التاريخ', dataIndex: 'changedAt' },
  ];

  return (
    <div>
      <Button icon={<ArrowRightOutlined />} onClick={() => navigate('/fees')} style={{ marginBottom: 16 }}>العودة للرسوم</Button>
      <Card style={{ marginBottom: 16 }}>
        <Descriptions title="تفاصيل اتفاقية الرسوم" bordered column={2}>
          <Descriptions.Item label="العميل">{feeData.customerName}</Descriptions.Item>
          <Descriptions.Item label="رقم القضية">{feeData.caseNumber || '-'}</Descriptions.Item>
          <Descriptions.Item label="المبلغ الإجمالي">{feeData.totalAmount}</Descriptions.Item>
          <Descriptions.Item label="المدفوع"><Tag color="green">{feeData.paidAmount || '0'}</Tag></Descriptions.Item>
          <Descriptions.Item label="المتبقي"><Tag color="red">{feeData.remainingAmount || '0'}</Tag></Descriptions.Item>
          <Descriptions.Item label="تاريخ الاتفاقية">{feeData.agreementDate}</Descriptions.Item>
          <Descriptions.Item label="ملاحظات" span={2}>{feeData.notes}</Descriptions.Item>
        </Descriptions>
      </Card>

      <Row gutter={16}>
        <Col span={14}>
          <Card title="الدفعات" extra={<Button type="primary" icon={<PlusOutlined />} onClick={() => setPayModalOpen(true)}>إضافة دفعة</Button>}>
            <Table columns={payColumns} dataSource={payments} rowKey="_id" size="small" pagination={false} />
          </Card>
        </Col>
        <Col span={10}>
          <Card title="سجل التعديلات" extra={<Button icon={<EditOutlined />} onClick={() => { editForm.setFieldsValue({ newTotalFee: feeData.totalAmount }); setEditModalOpen(true); }}>تعديل المبلغ</Button>}>
            <Table columns={histColumns} dataSource={history} rowKey="_id" size="small" pagination={false} />
          </Card>
        </Col>
      </Row>

      <Modal title="إضافة دفعة" open={payModalOpen} onOk={handleAddPayment} onCancel={() => setPayModalOpen(false)} confirmLoading={submitting} okText="حفظ" cancelText="إلغاء" destroyOnClose>
        <Form form={payForm} layout="vertical">
          <Form.Item name="amount" label="المبلغ" rules={[{ required: true }]}><Input type="number" /></Form.Item>
          <Form.Item name="paymentDate" label="تاريخ الدفع" rules={[{ required: true }]}><Input type="date" /></Form.Item>
          <Form.Item name="notes" label="ملاحظات" rules={[{ required: true }]}><Input.TextArea rows={2} /></Form.Item>
        </Form>
      </Modal>

      <Modal title="تعديل المبلغ الإجمالي" open={editModalOpen} onOk={handleEditAmount} onCancel={() => setEditModalOpen(false)} confirmLoading={submitting} okText="حفظ" cancelText="إلغاء" destroyOnClose>
        <Form form={editForm} layout="vertical">
          <Form.Item name="newTotalFee" label="المبلغ الجديد" rules={[{ required: true }]}><Input type="number" /></Form.Item>
          <Form.Item name="reason" label="سبب التعديل" rules={[{ required: true }]}><Input /></Form.Item>
          <Form.Item name="changedBy" label="بواسطة" rules={[{ required: true }]}><Input defaultValue="المحامي" /></Form.Item>
        </Form>
      </Modal>
    </div>
  );
}

