import { useState, useEffect, useCallback } from 'react';
import { Table, Button, Modal, Form, Input, Upload, Space, Popconfirm, message, Card, Typography, Row, Col } from 'antd';
import { PlusOutlined, DeleteOutlined, DownloadOutlined, UploadOutlined } from '@ant-design/icons';
import { createCrudApi, fileApi } from '../api/client';

const { Title } = Typography;
const templatesApi = createCrudApi('/templates');

export default function Templates() {
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [form] = Form.useForm();
  const [uploading, setUploading] = useState(false);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try { const res = await templatesApi.getAll(); setData(res.data.data || res.data || []); }
    catch { message.error('حدث خطأ'); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { fetchData(); }, [fetchData]);

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      const file = values.file?.[0]?.originFileObj || values.file;
      if (!file) { message.error('يرجى اختيار ملف'); return; }
      setUploading(true);
      const uploadRes = await fileApi.upload(file);
      const fileId = uploadRes.data.data?.fileId || uploadRes.data.fileId;
      const fileName = uploadRes.data.data?.fileName || file.name;
      await templatesApi.create({ title: values.title, category: values.category || '', documentType: values.documentType || '', fileId, fileName, notes: values.notes || '' });
      message.success('تم رفع القالب');
      setModalOpen(false);
      form.resetFields();
      fetchData();
    } catch (e: any) { if (!e?.errorFields) message.error('حدث خطأ'); }
    finally { setUploading(false); }
  };

  const handleDelete = async (id: string) => {
    try { await templatesApi.delete(id); message.success('تم الحذف'); fetchData(); }
    catch { message.error('حدث خطأ'); }
  };

  const columns = [
    { title: 'العنوان', dataIndex: 'title' },
    { title: 'الفئة', dataIndex: 'category' },
    { title: 'النوع', dataIndex: 'documentType' },
    { title: 'التاريخ', dataIndex: 'createdDate' },
    { title: 'إجراءات', render: (_: any, r: any) => (
      <Space>
        <Button type="link" icon={<DownloadOutlined />} href={fileApi.getUrl(r.fileId)} target="_blank">تحميل</Button>
        <Popconfirm title="حذف؟" onConfirm={() => handleDelete(r._id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>
      </Space>
    )},
  ];

  return (
    <div>
      <Row justify="space-between" align="middle" style={{ marginBottom: 16 }}>
        <Col><Title level={3} style={{ margin: 0 }}>قوالب المستندات</Title></Col>
        <Col><Button type="primary" icon={<PlusOutlined />} onClick={() => setModalOpen(true)}>رفع قالب</Button></Col>
      </Row>
      <Card><Table columns={columns} dataSource={data} rowKey="_id" loading={loading} /></Card>
      <Modal title="رفع قالب مستند" open={modalOpen} onOk={handleSubmit} onCancel={() => setModalOpen(false)} confirmLoading={uploading} okText="رفع" cancelText="إلغاء" destroyOnClose>
        <Form form={form} layout="vertical">
          <Form.Item name="title" label="العنوان" rules={[{ required: true }]}><Input placeholder="عنوان القالب" /></Form.Item>
          <Row gutter={16}>
            <Col span={12}><Form.Item name="category" label="الفئة"><Input placeholder="الفئة" /></Form.Item></Col>
            <Col span={12}><Form.Item name="documentType" label="النوع"><Input placeholder="النوع" /></Form.Item></Col>
          </Row>
          <Form.Item name="notes" label="ملاحظات"><Input.TextArea rows={2} /></Form.Item>
          <Form.Item name="file" label="الملف" rules={[{ required: true }]} valuePropName="fileList" getValueFromEvent={e => Array.isArray(e) ? e : e?.fileList}>
            <Upload beforeUpload={() => false} maxCount={1}><Button icon={<UploadOutlined />}>اختيار ملف</Button></Upload>
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
}

import { useState, useEffect } from 'react';
