import { useEffect, useState } from 'react';
import { Card, Col, Row, Statistic, Table, Typography, Spin, message } from 'antd';
import type { ColumnsType } from 'antd/es/table';
import {
  TeamOutlined,
  FolderOpenOutlined,
  CalendarOutlined,
  DollarOutlined,
  CheckCircleOutlined,
  ClockCircleOutlined,
  ShoppingCartOutlined,
} from '@ant-design/icons';
import dayjs from 'dayjs';
import api from '../api/client';

const { Title } = Typography;

interface DashboardStats {
  totalCustomers: number;
  totalCases: number;
  upcomingSessions: number;
  totalFees: number;
  collectedFees: number;
  remainingFees: number;
  totalExpenses: number;
}

interface SessionItem {
  id: string;
  title?: string;
  caseTitle?: string;
  caseNumber?: string;
  sessionDate?: string;
  date?: string;
  court?: string;
  customerName?: string;
  notes?: string;
}

export default function Dashboard() {
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [sessions, setSessions] = useState<SessionItem[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [statsRes, sessionsRes] = await Promise.all([
          api.get<DashboardStats>('/dashboard'),
          api.get<SessionItem[]>('/sessions', { params: { upcoming: true } }),
        ]);
        setStats(statsRes.data);
        setSessions(Array.isArray(sessionsRes.data) ? sessionsRes.data : []);
      } catch (error) {
        console.error(error);
        message.error('تعذر تحميل بيانات لوحة التحكم');
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const sessionColumns: ColumnsType<SessionItem> = [
    {
      title: 'الموضوع',
      key: 'title',
      render: (_, record) => record.title || record.caseTitle || '—',
    },
    {
      title: 'رقم القضية',
      key: 'caseNumber',
      render: (_, record) => record.caseNumber || '—',
    },
    {
      title: 'التاريخ والوقت',
      key: 'sessionDate',
      render: (_, record) => {
        const d = record.sessionDate || record.date;
        return d ? dayjs(d).format('YYYY-MM-DD HH:mm') : '—';
      },
    },
    {
      title: 'المحكمة',
      key: 'court',
      render: (_, record) => record.court || '—',
    },
    {
      title: 'العميل',
      key: 'customerName',
      render: (_, record) => record.customerName || '—',
    },
    {
      title: 'ملاحظات',
      key: 'notes',
      render: (_, record) => record.notes || '—',
      ellipsis: true,
    },
  ];

  if (loading) {
    return (
      <div style={{ display: 'flex', justifyContent: 'center', padding: 80 }}>
        <Spin size="large" />
      </div>
    );
  }

  const statsList = [
    { title: 'إجمالي العملاء', value: stats?.totalCustomers ?? 0, icon: <TeamOutlined />, color: '#2563eb' },
    { title: 'إجمالي القضايا', value: stats?.totalCases ?? 0, icon: <FolderOpenOutlined />, color: '#7c3aed' },
    { title: 'الجلسات القادمة', value: stats?.upcomingSessions ?? 0, icon: <CalendarOutlined />, color: '#0891b2' },
    { title: 'إجمالي الرسوم', value: stats?.totalFees ?? 0, icon: <DollarOutlined />, color: '#16a34a' },
    { title: 'الرسوم المحصّلة', value: stats?.collectedFees ?? 0, icon: <CheckCircleOutlined />, color: '#15803d' },
    { title: 'الرسوم المتبقية', value: stats?.remainingFees ?? 0, icon: <ClockCircleOutlined />, color: '#dc2626' },
    { title: 'إجمالي المصاريف', value: stats?.totalExpenses ?? 0, icon: <ShoppingCartOutlined />, color: '#ea580c' },
  ];

  return (
    <div>
      <Title level={3} style={{ marginBottom: 24 }}>لوحة التحكم</Title>

      <Row gutter={[16, 16]}>
        {statsList.map((s) => (
          <Col xs={24} sm={12} md={8} lg={6} key={s.title}>
            <Card hoverable>
              <Statistic
                title={s.title}
                value={s.value}
                prefix={s.icon}
                valueStyle={{ color: s.color }}
              />
            </Card>
          </Col>
        ))}
      </Row>

      <Card title="الجلسات القادمة" style={{ marginTop: 24 }}>
        <Table
          columns={sessionColumns}
          dataSource={sessions}
          rowKey="id"
          pagination={{ pageSize: 5 }}
          locale={{ emptyText: 'لا توجد جلسات قادمة' }}
        />
      </Card>
    </div>
  );
}

import { useEffect, useState } from 'react';
import {
  Button,
  Card,
  Form,
  Input,
  Modal,
  Popconfirm,
  Space,
  Table,
  Typography,
  message,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import {
  PlusOutlined,
  EyeOutlined,
  EditOutlined,
  DeleteOutlined,
  SearchOutlined,
} from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import { createCrudApi } from '../api/client';

const { Title } = Typography;

interface Customer {
  id: string;
  name: string;
  address?: string;
  phone: string;
  identityNumber?: string;
  whatsappNumber?: string;
  email?: string;
  notes?: string;
}

interface FormValues {
  name: string;
  address?: string;
  phone: string;
  identityNumber?: string;
  whatsappNumber?: string;
  email?: string;
  notes?: string;
}

const customersApi = createCrudApi<Customer>('customers');

export default function Customers() {
  const navigate = useNavigate();
  const [form] = Form.useForm<FormValues>();
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Customer | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const fetchCustomers = async () => {
    setLoading(true);
    try {
      const { data } = await customersApi.getAll();
      setCustomers(Array.isArray(data) ? data : []);
    } catch (error) {
      console.error(error);
      message.error('تعذر تحميل قائمة العملاء');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCustomers();
  }, []);

  const filtered = customers.filter((c) => {
    const q = search.trim().toLowerCase();
    if (!q) return true;
    return (
      (c.name || '').toLowerCase().includes(q) ||
      (c.phone || '').toLowerCase().includes(q)
    );
  });

  const openAdd = () => {
    setEditing(null);
    form.resetFields();
    setModalOpen(true);
  };

  const openEdit = (customer: Customer) => {
    setEditing(customer);
    form.setFieldsValue(customer);
    setModalOpen(true);
  };

  const handleSubmit = async () => {
    let values: FormValues;
    try {
      values = await form.validateFields();
    } catch {
      return; // أخطاء التحقق يعرضها النموذج تلقائيًا
    }

    setSubmitting(true);
    try {
      if (editing) {
        await customersApi.update(editing.id, values);
        message.success('تم تحديث بيانات العميل');
      } else {
        await customersApi.create(values);
        message.success('تم إضافة العميل بنجاح');
      }
      setModalOpen(false);
      fetchCustomers();
    } catch (error) {
      console.error(error);
      message.error('حدث خطأ أثناء الحفظ');
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (customer: Customer) => {
    try {
      await customersApi.delete(customer.id);
      message.success('تم حذف العميل');
      fetchCustomers();
    } catch (error) {
      console.error(error);
      message.error('تعذر حذف العميل');
    }
  };

  const columns: ColumnsType<Customer> = [
    { title: 'الاسم', dataIndex: 'name', key: 'name' },
    { title: 'الهاتف', dataIndex: 'phone', key: 'phone' },
    {
      title: 'واتساب',
      dataIndex: 'whatsappNumber',
      key: 'whatsappNumber',
      render: (v: string) => v || '—',
    },
    {
      title: 'البريد الإلكتروني',
      dataIndex: 'email',
      key: 'email',
      render: (v: string) => v || '—',
    },
    {
      title: 'إجراءات',
      key: 'actions',
      width: 160,
      render: (_, record) => (
        <Space>
          <Button
            type="link"
            icon={<EyeOutlined />}
            onClick={() => navigate(`/customers/${record.id}`)}
          />
          <Button
            type="link"
            icon={<EditOutlined />}
            onClick={() => openEdit(record)}
          />
          <Popconfirm
            title="هل أنت متأكد من حذف هذا العميل؟"
            okText="نعم"
            cancelText="إلغاء"
            onConfirm={() => handleDelete(record)}
          >
            <Button type="link" danger icon={<DeleteOutlined />} />
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <div>
      <Title level={3}>العملاء</Title>
      <Card>
        <Space style={{ marginBottom: 16 }} wrap>
          <Input
            placeholder="بحث بالاسم أو الهاتف"
            prefix={<SearchOutlined />}
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            allowClear
            style={{ width: 280 }}
          />
          <Button type="primary" icon={<PlusOutlined />} onClick={openAdd}>
            إضافة عميل
          </Button>
        </Space>

        <Table
          columns={columns}
          dataSource={filtered}
          rowKey="id"
          loading={loading}
          pagination={{ pageSize: 10 }}
          locale={{ emptyText: 'لا يوجد عملاء' }}
        />
      </Card>

      <Modal
        title={editing ? 'تعديل بيانات العميل' : 'إضافة عميل جديد'}
        open={modalOpen}
        onOk={handleSubmit}
        onCancel={() => setModalOpen(false)}
        confirmLoading={submitting}
        okText="حفظ"
        cancelText="إلغاء"
        forceRender
      >
        <Form form={form} layout="vertical" style={{ marginTop: 16 }}>
          <Form.Item
            name="name"
            label="الاسم"
            rules={[{ required: true, message: 'الرجاء إدخال الاسم' }]}
          >
            <Input />
          </Form.Item>
          <Form.Item
            name="phone"
            label="الهاتف"
            rules={[{ required: true, message: 'الرجاء إدخال رقم الهاتف' }]}
          >
            <Input />
          </Form.Item>
          <Form.Item name="identityNumber" label="رقم الهوية">
            <Input />
          </Form.Item>
          <Form.Item name="whatsappNumber" label="رقم الواتساب">
            <Input />
          </Form.Item>
          <Form.Item name="email" label="البريد الإلكتروني">
            <Input />
          </Form.Item>
          <Form.Item name="address" label="العنوان">
            <Input />
          </Form.Item>
          <Form.Item name="notes" label="ملاحظات">
            <Input.TextArea rows={3} />
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import {
  Button,
  Card,
  Descriptions,
  Popconfirm,
  Space,
  Spin,
  Table,
  Tabs,
  Typography,
  Upload,
  message,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import {
  ArrowRightOutlined,
  DeleteOutlined,
  EyeOutlined,
  FileOutlined,
  UploadOutlined,
} from '@ant-design/icons';
import { useNavigate, useParams } from 'react-router-dom';
import dayjs from 'dayjs';
import api, { createCrudApi, fileApi } from '../api/client';

const { Title } = Typography;

interface Customer {
  id: string;
  name: string;
  address?: string;
  phone: string;
  identityNumber?: string;
  whatsappNumber?: string;
  email?: string;
  notes?: string;
}

interface CaseItem {
  id: string;
  caseNumber?: string;
  title?: string;
  customerId?: string;
  court?: string;
  caseType?: string;
  status?: string;
  filedDate?: string;
  nextSessionDate?: string;
}

interface FeeItem {
  id: string;
  customerId?: string;
  amount?: number;
  collectedAmount?: number;
  paidAmount?: number;
  agreementType?: string;
  status?: string;
  date?: string;
  notes?: string;
}

interface ExpenseItem {
  id: string;
  customerId?: string;
  amount?: number;
  description?: string;
  date?: string;
  category?: string;
}

interface CustomerDocument {
  id: string;
  customerId?: string;
  name?: string;
  fileName?: string;
  fileId?: string;
  filePath?: string;
  uploadedAt?: string;
  createdAt?: string;
}

const customersApi = createCrudApi<Customer>('customers');
const casesApi = createCrudApi<CaseItem>('cases');
const feesApi = createCrudApi<FeeItem>('fees');
const expensesApi = createCrudApi<ExpenseItem>('expenses');

const formatCurrency = (value?: number | null): string => {
  if (value == null) return '—';
  return Number(value).toLocaleString('ar-EG');
};

const formatDate = (value?: string): string => {
  if (!value) return '—';
  return dayjs(value).format('YYYY-MM-DD');
};

export default function CustomerDetail() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();

  const [customer, setCustomer] = useState<Customer | null>(null);
  const [loadingCustomer, setLoadingCustomer] = useState(true);

  const [cases, setCases] = useState<CaseItem[]>([]);
  const [loadingCases, setLoadingCases] = useState(false);

  const [documents, setDocuments] = useState<CustomerDocument[]>([]);
  const [loadingDocuments, setLoadingDocuments] = useState(false);
  const [uploading, setUploading] = useState(false);

  const [fees, setFees] = useState<FeeItem[]>([]);
  const [loadingFees, setLoadingFees] = useState(false);

  const [expenses, setExpenses] = useState<ExpenseItem[]>([]);
  const [loadingExpenses, setLoadingExpenses] = useState(false);

  const fetchCustomer = useCallback(async () => {
    if (!id) return;
    setLoadingCustomer(true);
    try {
      const { data } = await customersApi.getById(id);
      setCustomer(data);
    } catch (error) {
      console.error(error);
      message.error('تعذر تحميل بيانات العميل');
    } finally {
      setLoadingCustomer(false);
    }
  }, [id]);

  const fetchCases = useCallback(async () => {
    if (!id) return;
    setLoadingCases(true);
    try {
      const { data } = await casesApi.getAll();
      const list = Array.isArray(data) ? data : [];
      setCases(list.filter((c) => String(c.customerId) === String(id)));
    } catch (error) {
      console.error(error);
    } finally {
      setLoadingCases(false);
    }
  }, [id]);

  const fetchDocuments = useCallback(async () => {
    if (!id) return;
    setLoadingDocuments(true);
    try {
      const { data } = await api.get<CustomerDocument[]>(
        `/customer-documents/${id}`,
      );
      setDocuments(Array.isArray(data) ? data : []);
    } catch (error) {
      console.error(error);
    } finally {
      setLoadingDocuments(false);
    }
  }, [id]);

  const fetchFees = useCallback(async () => {
    if (!id) return;
    setLoadingFees(true);
    try {
      const { data } = await feesApi.getAll();
      const list = Array.isArray(data) ? data : [];
      setFees(list.filter((f) => String(f.customerId) === String(id)));
    } catch (error) {
      console.error(error);
    } finally {
      setLoadingFees(false);
    }
  }, [id]);

  const fetchExpenses = useCallback(async () => {
    if (!id) return;
    setLoadingExpenses(true);
    try {
      const { data } = await expensesApi.getAll();
      const list = Array.isArray(data) ? data : [];
      setExpenses(list.filter((e) => String(e.customerId) === String(id)));
    } catch (error) {
      console.error(error);
    } finally {
      setLoadingExpenses(false);
    }
  }, [id]);

  useEffect(() => {
    fetchCustomer();
    fetchCases();
    fetchDocuments();
    fetchFees();
    fetchExpenses();
  }, [fetchCustomer, fetchCases, fetchDocuments, fetchFees, fetchExpenses]);

  const handleUpload = async (file: File): Promise<boolean> => {
    if (!id) return false;
    setUploading(true);
    try {
      const uploadRes = await fileApi.upload(file);
      const fileId =
        uploadRes.data?.id || uploadRes.data?.fileId || uploadRes.data?._id;
      await api.post('/customer-documents', {
        customerId: id,
        name: file.name,
        fileName: file.name,
        fileId,
      });
      message.success('تم رفع المستند بنجاح');
      fetchDocuments();
    } catch (error) {
      console.error(error);
      message.error('تعذر رفع المستند');
    } finally {
      setUploading(false);
    }
    return false; // منع الرفع التلقائي من antd
  };

  const handleDeleteDocument = async (doc: CustomerDocument) => {
    try {
      await api.delete(`/customer-documents/${doc.id}`);
      message.success('تم حذف المستند');
      fetchDocuments();
    } catch (error) {
      console.error(error);
      message.error('تعذر حذف المستند');
    }
  };

  const caseColumns: ColumnsType<CaseItem> = [
    {
      title: 'رقم القضية',
      dataIndex: 'caseNumber',
      key: 'caseNumber',
      render: (v: string) => v || '—',
    },
    {
      title: 'عنوان القضية',
      dataIndex: 'title',
      key: 'title',
      render: (v: string) => v || '—',
    },
    {
      title: 'المحكمة',
      dataIndex: 'court',
      key: 'court',
      render: (v: string) => v || '—',
    },
    {
      title: 'النوع',
      dataIndex: 'caseType',
      key: 'caseType',
      render: (v: string) => v || '—',
    },
    {
      title: 'الحالة',
      dataIndex: 'status',
      key: 'status',
      render: (v: string) => v || '—',
    },
    {
      title: 'تاريخ القيد',
      dataIndex: 'filedDate',
      key: 'filedDate',
      render: (v: string) => formatDate(v),
    },
  ];

  const documentColumns: ColumnsType<CustomerDocument> = [
    {
      title: 'اسم المستند',
      key: 'name',
      render: (_, record) => (
        <Space>
          <FileOutlined />
          <span>{record.name || record.fileName || 'مستند'}</span>
        </Space>
      ),
    },
    {
      title: 'تاريخ الرفع',
      key: 'uploadedAt',
      render: (_, record) => {
        const d = record.uploadedAt || record.createdAt;
        return d ? dayjs(d).format('YYYY-MM-DD HH:mm') : '—';
      },
    },
    {
      title: 'إجراءات',
      key: 'actions',
      render: (_, record) => (
        <Space>
          {record.fileId && (
            <Button
              type="link"
              icon={<EyeOutlined />}
              onClick={() => window.open(fileApi.getUrl(record.fileId!), '_blank')}
            >
              عرض
            </Button>
          )}
          <Popconfirm
            title="هل أنت متأكد من حذف هذا المستند؟"
            okText="نعم"
            cancelText="إلغاء"
            onConfirm={() => handleDeleteDocument(record)}
          >
            <Button type="link" danger icon={<DeleteOutlined />} />
          </Popconfirm>
        </Space>
      ),
    },
  ];

  const feeColumns: ColumnsType<FeeItem> = [
    {
      title: 'نوع الاتفاق',
      dataIndex: 'agreementType',
      key: 'agreementType',
      render: (v: string) => v || '—',
    },
    {
      title: 'المبلغ',
      dataIndex: 'amount',
      key: 'amount',
      render: (v?: number) => formatCurrency(v),
    },
    {
      title: 'المحصّل',
      key: 'collected',
      render: (_, record) => formatCurrency(record.collectedAmount ?? record.paidAmount),
    },
    {
      title: 'الحالة',
      dataIndex: 'status',
      key: 'status',
      render: (v: string) => v || '—',
    },
    {
      title: 'التاريخ',
      dataIndex: 'date',
      key: 'date',
      render: (v: string) => formatDate(v),
    },
  ];

  const expenseColumns: ColumnsType<ExpenseItem> = [
    {
      title: 'الوصف',
      dataIndex: 'description',
      key: 'description',
      render: (v: string) => v || '—',
    },
    {
      title: 'الفئة',
      dataIndex: 'category',
      key: 'category',
      render: (v: string) => v || '—',
    },
    {
      title: 'المبلغ',
      dataIndex: 'amount',
      key: 'amount',
      render: (v?: number) => formatCurrency(v),
    },
    {
      title: 'التاريخ',
      dataIndex: 'date',
      key: 'date',
      render: (v: string) => formatDate(v),
    },
  ];

  if (loadingCustomer) {
    return (
      <div style={{ display: 'flex', justifyContent: 'center', padding: 80 }}>
        <Spin size="large" />
      </div>
    );
  }

  if (!customer) {
    return (
      <div>
        <Button
          icon={<ArrowRightOutlined />}
          onClick={() => navigate('/customers')}
          style={{ marginBottom: 16 }}
        >
          رجوع للعملاء
        </Button>
        <Title level={4}>لم يتم العثور على العميل</Title>
      </div>
    );
  }

  return (
    <div>
      <Button
        icon={<ArrowRightOutlined />}
        onClick={() => navigate('/customers')}
        style={{ marginBottom: 16 }}
      >
        رجوع للعملاء
      </Button>

      <Card style={{ marginBottom: 16 }}>
        <Descriptions title={customer.name} column={{ xs: 1, sm: 2, md: 3 }}>
          <Descriptions.Item label="الهاتف">{customer.phone || '—'}</Descriptions.Item>
          <Descriptions.Item label="رقم الهوية">{customer.identityNumber || '—'}</Descriptions.Item>
          <Descriptions.Item label="واتساب">{customer.whatsappNumber || '—'}</Descriptions.Item>
          <Descriptions.Item label="البريد الإلكتروني">{customer.email || '—'}</Descriptions.Item>
          <Descriptions.Item label="العنوان">{customer.address || '—'}</Descriptions.Item>
          <Descriptions.Item label="ملاحظات">{customer.notes || '—'}</Descriptions.Item>
        </Descriptions>
      </Card>

      <Card>
        <Tabs
          defaultActiveKey="cases"
          items={[
            {
              key: 'cases',
              label: 'القضايا',
              children: (
                <Table
                  columns={caseColumns}
                  dataSource={cases}
                  rowKey="id"
                  loading={loadingCases}
                  pagination={{ pageSize: 5 }}
                  locale={{ emptyText: 'لا توجد قضايا لهذا العميل' }}
                />
              ),
            },
            {
              key: 'documents',
              label: 'المستندات',
              children: (
                <>
                  <Upload
                    beforeUpload={handleUpload}
                    showUploadList={false}
                    multiple={false}
                  >
                    <Button
                      type="primary"
                      icon={<UploadOutlined />}
                      loading={uploading}
                      style={{ marginBottom: 16 }}
                    >
                      رفع مستند
                    </Button>
                  </Upload>
                  <Table
                    columns={documentColumns}
                    dataSource={documents}
                    rowKey="id"
                    loading={loadingDocuments}
                    pagination={{ pageSize: 5 }}
                    locale={{ emptyText: 'لا توجد مستندات' }}
                  />
                </>
              ),
            },
            {
              key: 'fees',
              label: 'اتفاقيات الرسوم',
              children: (
                <Table
                  columns={feeColumns}
                  dataSource={fees}
                  rowKey="id"
                  loading={loadingFees}
                  pagination={{ pageSize: 5 }}
                  locale={{ emptyText: 'لا توجد اتفاقيات رسوم' }}
                />
              ),
            },
            {
              key: 'expenses',
              label: 'المصاريف',
              children: (
                <Table
                  columns={expenseColumns}
                  dataSource={expenses}
                  rowKey="id"
                  loading={loadingExpenses}
                  pagination={{ pageSize: 5 }}
                  locale={{ emptyText: 'لا توجد مصاريف' }}
                />
              ),
            },
          ]}
        />
      </Card>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { Table, Button, Modal, Form, Input, Select, Space, Popconfirm, message, Card, Typography, Row, Col } from 'antd';
import { PlusOutlined, EditOutlined, DeleteOutlined, SearchOutlined, SyncOutlined } from '@ant-design/icons';
import { createCrudApi } from '../api/client';

const { Title } = Typography;

const casesApi = createCrudApi('/cases');
const customersApi = createCrudApi('/customers');
const courtsApi = createCrudApi('/courts');
const caseTypesApi = createCrudApi('/case-types');

export default function Cases() {
  const navigate = useNavigate();
  const [cases, setCases] = useState<any[]>([]);
  const [customers, setCustomers] = useState<any[]>([]);
  const [courts, setCourts] = useState<any[]>([]);
  const [caseTypes, setCaseTypes] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [form] = Form.useForm();
  const [submitting, setSubmitting] = useState(false);

  const fetchAll = useCallback(async () => {
    setLoading(true);
    try {
      const [casesRes, custRes, courtsRes, typesRes] = await Promise.all([
        casesApi.getAll(), customersApi.getAll(), courtsApi.getAll(), caseTypesApi.getAll(),
      ]);
      setCases(casesRes.data.data || casesRes.data || []);
      setCustomers(custRes.data.data || custRes.data || []);
      setCourts(courtsRes.data.data || courtsRes.data || []);
      setCaseTypes(typesRes.data.data || typesRes.data || []);
    } catch { message.error('حدث خطأ أثناء تحميل البيانات'); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { fetchAll(); }, [fetchAll]);

  const filtered = cases.filter((c: any) => {
    if (!search) return true;
    const q = search.toLowerCase();
    return (c.caseNumber || '').includes(q) || (c.customerName || '').toLowerCase().includes(q);
  });

  const openModal = (record?: any) => {
    setEditing(record || null);
    if (record) form.setFieldsValue(record);
    else form.resetFields();
    setModalOpen(true);
  };

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      setSubmitting(true);
      if (editing?._id) await casesApi.update(editing._id, values);
      else await casesApi.create(values);
      message.success(editing ? 'تم تحديث القضية' : 'تم إضافة القضية');
      setModalOpen(false);
      fetchAll();
    } catch (e: any) { if (!e?.errorFields) message.error('حدث خطأ'); }
    finally { setSubmitting(false); }
  };

  const handleDelete = async (id: string) => {
    try { await casesApi.delete(id); message.success('تم حذف القضية'); fetchAll(); }
    catch { message.error('حدث خطأ أثناء الحذف'); }
  };

  const columns = [
    { title: 'رقم القضية', dataIndex: 'caseNumber', render: (t: string, r: any) => <a onClick={() => navigate(`/cases/${r._id}`)}>{t}</a> },
    { title: 'السنة', dataIndex: 'caseYear' },
    { title: 'العميل', dataIndex: 'customerName' },
    { title: 'الخصم', dataIndex: 'opponentName' },
    { title: 'المحكمة', dataIndex: 'courtName' },
    { title: 'النوع', dataIndex: 'caseTypeName' },
    {
      title: 'إجراءات', key: 'actions',
      render: (_: any, r: any) => (
        <Space>
          <Button type="text" icon={<EditOutlined />} onClick={(e) => { e.stopPropagation(); openModal(r); }} />
          <Popconfirm title="هل أنت متأكد من حذف هذه القضية؟" onConfirm={() => handleDelete(r._id)} okText="نعم" cancelText="لا">
            <Button type="text" danger icon={<DeleteOutlined />} onClick={(e) => e.stopPropagation()} />
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <div>
      <Row justify="space-between" align="middle" style={{ marginBottom: 16 }}>
        <Col><Title level={3} style={{ margin: 0 }}>القضايا</Title></Col>
        <Col><Button type="primary" icon={<PlusOutlined />} onClick={() => openModal()}>إضافة قضية</Button></Col>
      </Row>
      <Card>
        <Input placeholder="ابحث برقم القضية أو اسم العميل" prefix={<SearchOutlined />} value={search} onChange={e => setSearch(e.target.value)} allowClear style={{ marginBottom: 16, maxWidth: 400 }} />
        <Table columns={columns} dataSource={filtered} rowKey="_id" loading={loading} onRow={(r) => ({ onClick: () => navigate(`/cases/${r._id}`), style: { cursor: 'pointer' } })} scroll={{ x: 800 }} />
      </Card>
      <Modal title={editing ? 'تعديل قضية' : 'إضافة قضية'} open={modalOpen} onOk={handleSubmit} onCancel={() => setModalOpen(false)} confirmLoading={submitting} okText="حفظ" cancelText="إلغاء" width={720} destroyOnClose>
        <Form form={form} layout="vertical">
          <Row gutter={16}>
            <Col span={12}><Form.Item name="customerId" label="العميل" rules={[{ required: true, message: 'يرجى اختيار العميل' }]}><Select showSearch placeholder="اختر العميل" optionFilterProp="children" options={customers.map((c: any) => ({ value: c._id, label: c.name }))} /></Form.Item></Col>
            <Col span={12}><Form.Item name="opponentName" label="اسم الخصم" rules={[{ required: true, message: 'يرجى إدخال اسم الخصم' }]}><Input placeholder="اسم الخصم" /></Form.Item></Col>
          </Row>
          <Row gutter={16}>
            <Col span={12}><Form.Item name="clientCapacity" label="صفة الموكل"><Input placeholder="صفة الموكل" /></Form.Item></Col>
            <Col span={12}><Form.Item name="opponentCapacity" label="صفة الخصم"><Input placeholder="صفة الخصم" /></Form.Item></Col>
          </Row>
          <Row gutter={16}>
            <Col span={12}><Form.Item name="courtId" label="المحكمة" rules={[{ required: true, message: 'يرجى اختيار المحكمة' }]}><Select showSearch placeholder="اختر المحكمة" optionFilterProp="children" options={courts.map((c: any) => ({ value: c._id, label: c.name }))} /></Form.Item></Col>
            <Col span={12}><Form.Item name="circuitNumber" label="رقم الدائرة"><Input placeholder="رقم الدائرة" /></Form.Item></Col>
          </Row>
          <Row gutter={16}>
            <Col span={12}><Form.Item name="caseNumber" label="رقم القضية" rules={[{ required: true, message: 'يرجى إدخال رقم القضية' }]}><Input placeholder="رقم القضية" /></Form.Item></Col>
            <Col span={12}><Form.Item name="caseYear" label="سنة القضية" rules={[{ required: true, message: 'يرجى إدخال سنة القضية' }]}><Input placeholder="سنة القضية" /></Form.Item></Col>
          </Row>
          <Row gutter={16}>
            <Col span={12}><Form.Item name="caseTypeId" label="نوع القضية" rules={[{ required: true, message: 'يرجى اختيار نوع القضية' }]}><Select showSearch placeholder="اختر نوع القضية" optionFilterProp="children" options={caseTypes.map((c: any) => ({ value: c._id, label: c.name }))} /></Form.Item></Col>
            <Col span={12}><Form.Item name="caseSubject" label="موضوع القضية"><Input placeholder="موضوع القضية" /></Form.Item></Col>
          </Row>
        </Form>
      </Modal>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Tabs, Table, Modal, Form, Input, Button, Card, Descriptions, Space, Upload, message, Spin, Typography, Row, Col, Select, Popconfirm } from 'antd';
import { UploadOutlined, PlusOutlined, DownloadOutlined, DeleteOutlined, ArrowRightOutlined } from '@ant-design/icons';
import { createCrudApi, fileApi } from '../api/client';

const { Title } = Typography;

const casesApi = createCrudApi('/cases');
const sessionsApi = createCrudApi('/sessions');
const caseDocsApi = createCrudApi('/case-documents');
const announcementsApi = createCrudApi('/announcements');
const feesApi = createCrudApi('/fees');
const expensesApi = createCrudApi('/expenses');
const courtsApi = createCrudApi('/courts');

export default function CaseDetail() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [caseData, setCaseData] = useState<any>(null);
  const [sessions, setSessions] = useState<any[]>([]);
  const [documents, setDocuments] = useState<any[]>([]);
  const [announcements, setAnnouncements] = useState<any[]>([]);
  const [fees, setFees] = useState<any[]>([]);
  const [expenses, setExpenses] = useState<any[]>([]);
  const [courts, setCourts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [sessionModalOpen, setSessionModalOpen] = useState(false);
  const [sessionForm] = Form.useForm();
  const [docModalOpen, setDocModalOpen] = useState(false);
  const [docForm] = Form.useForm();
  const [uploading, setUploading] = useState(false);

  const fetchData = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    try {
      const [caseRes, sessRes, docsRes, annRes, feeRes, expRes, courtsRes] = await Promise.all([
        casesApi.getById(id),
        sessionsApi.getAll(),
        caseDocsApi.getAll(),
        announcementsApi.getAll(),
        feesApi.getAll(),
        expensesApi.getAll(),
        courtsApi.getAll(),
      ]);
      setCaseData(caseRes.data.data || caseRes.data);
      const allSessions = sessRes.data.data || sessRes.data || [];
      setSessions(allSessions.filter((s: any) => s.caseId === id || s.caseId?._id === id));
      const allDocs = docsRes.data.data || docsRes.data || [];
      setDocuments(allDocs.filter((d: any) => d.caseId === id || d.caseId?._id === id));
      const allAnn = annRes.data.data || annRes.data || [];
      setAnnouncements(allAnn.filter((a: any) => a.caseId === id || a.caseId?._id === id));
      const allFees = feeRes.data.data || feeRes.data || [];
      setFees(allFees.filter((f: any) => f.caseId === id || f.caseId?._id === id));
      const allExp = expRes.data.data || expRes.data || [];
      setExpenses(allExp.filter((e: any) => e.caseId === id || e.caseId?._id === id));
      setCourts(courtsRes.data.data || courtsRes.data || []);
    } catch { message.error('حدث خطأ أثناء تحميل بيانات القضية'); }
    finally { setLoading(false); }
  }, [id]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const handleAddSession = async () => {
    try {
      const values = await sessionForm.validateFields();
      await sessionsApi.create({ ...values, caseId: id });
      message.success('تم إضافة الجلسة');
      setSessionModalOpen(false);
      sessionForm.resetFields();
      fetchData();
    } catch (e: any) { if (!e?.errorFields) message.error('حدث خطأ'); }
  };

  const handleUploadDoc = async () => {
    try {
      const values = await docForm.validateFields();
      const file = values.file?.[0]?.originFileObj || values.file;
      if (!file) { message.error('يرجى اختيار ملف'); return; }
      setUploading(true);
      const uploadRes = await fileApi.upload(file);
      const fileId = uploadRes.data.data?.fileId || uploadRes.data.fileId;
      const fileName = uploadRes.data.data?.fileName || file.name;
      await caseDocsApi.create({ caseId: id, documentName: values.documentName, documentType: values.documentType || '', fileId, fileName, notes: values.notes || '' });
      message.success('تم رفع المستند');
      setDocModalOpen(false);
      docForm.resetFields();
      fetchData();
    } catch (e: any) { if (!e?.errorFields) message.error('حدث خطأ أثناء الرفع'); }
    finally { setUploading(false); }
  };

  const handleDeleteDoc = async (docId: string) => {
    try { await caseDocsApi.delete(docId); message.success('تم حذف المستند'); fetchData(); }
    catch { message.error('حدث خطأ'); }
  };

  const handleDeleteSession = async (sid: string) => {
    try { await sessionsApi.delete(sid); message.success('تم حذف الجلسة'); fetchData(); }
    catch { message.error('حدث خطأ'); }
  };

  if (loading) return <Spin size="large" style={{ display: 'flex', justifyContent: 'center', marginTop: 100 }} />;
  if (!caseData) return <div>القضية غير موجودة</div>;

  const sessionColumns = [
    { title: 'الجلسة #', dataIndex: 'sessionNumber' },
    { title: 'التاريخ', dataIndex: 'sessionDate' },
    { title: 'الموضوع', dataIndex: 'subject' },
    { title: 'النوع', dataIndex: 'sessionType' },
    { title: 'القرار', dataIndex: 'sessionDecision', ellipsis: true },
    { title: 'الجلسة القادمة', dataIndex: 'nextSessionDate' },
    { title: 'إجراءات', render: (_: any, r: any) => <Popconfirm title="حذف الجلسة؟" onConfirm={() => handleDeleteSession(r._id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm> },
  ];

  const docColumns = [
    { title: 'اسم المستند', dataIndex: 'documentName' },
    { title: 'النوع', dataIndex: 'documentType' },
    { title: 'التاريخ', dataIndex: 'createdDate' },
    {
      title: 'إجراءات', render: (_: any, r: any) => (
        <Space>
          <Button type="link" icon={<DownloadOutlined />} href={fileApi.getUrl(r.fileId)} target="_blank">تحميل</Button>
          <Popconfirm title="حذف المستند؟" onConfirm={() => handleDeleteDoc(r._id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>
        </Space>
      ),
    },
  ];

  const annColumns = [
    { title: 'رقم الإعلان', dataIndex: 'announcementNumber' },
    { title: 'المستلم', dataIndex: 'recipientName' },
    { title: 'الموضوع', dataIndex: 'subject', ellipsis: true },
    { title: 'المحضر', dataIndex: 'bailiffName' },
    { title: 'تاريخ التسليم', dataIndex: 'deliveryDate' },
  ];

  const feeColumns = [
    { title: 'العميل', dataIndex: 'customerName' },
    { title: 'المبلغ الإجمالي', dataIndex: 'totalAmount' },
    { title: 'المدفوع', dataIndex: 'paidAmount' },
    { title: 'المتبقي', dataIndex: 'remainingAmount' },
    { title: 'التاريخ', dataIndex: 'agreementDate' },
  ];

  const expColumns = [
    { title: 'التاريخ', dataIndex: 'expenseDate' },
    { title: 'الوصف', dataIndex: 'description' },
    { title: 'الفئة', dataIndex: 'category' },
    { title: 'المبلغ', dataIndex: 'amount' },
  ];

  return (
    <div>
      <Button icon={<ArrowRightOutlined />} onClick={() => navigate('/cases')} style={{ marginBottom: 16 }}>العودة للقضايا</Button>
      <Card style={{ marginBottom: 16 }}>
        <Descriptions title={`القضية رقم ${caseData.caseNumber} - ${caseData.caseYear}`} bordered column={2}>
          <Descriptions.Item label="العميل">{caseData.customerName || caseData.customerId?.name}</Descriptions.Item>
          <Descriptions.Item label="الخصم">{caseData.opponentName}</Descriptions.Item>
          <Descriptions.Item label="المحكمة">{caseData.courtName || caseData.courtId?.name}</Descriptions.Item>
          <Descriptions.Item label="نوع القضية">{caseData.caseTypeName || caseData.caseTypeId?.name}</Descriptions.Item>
          <Descriptions.Item label="رقم الدائرة">{caseData.circuitNumber}</Descriptions.Item>
          <Descriptions.Item label="الموضوع">{caseData.caseSubject}</Descriptions.Item>
          <Descriptions.Item label="صفة الموكل">{caseData.clientCapacity}</Descriptions.Item>
          <Descriptions.Item label="صفة الخصم">{caseData.opponentCapacity}</Descriptions.Item>
        </Descriptions>
      </Card>
      <Tabs items={[
        { key: 'sessions', label: 'الجلسات', children: (
          <div>
            <Button type="primary" icon={<PlusOutlined />} onClick={() => setSessionModalOpen(true)} style={{ marginBottom: 16 }}>إضافة جلسة</Button>
            <Table columns={sessionColumns} dataSource={sessions} rowKey="_id" size="small" />
          </div>
        )},
        { key: 'docs', label: 'المستندات', children: (
          <div>
            <Button type="primary" icon={<PlusOutlined />} onClick={() => setDocModalOpen(true)} style={{ marginBottom: 16 }}>رفع مستند</Button>
            <Table columns={docColumns} dataSource={documents} rowKey="_id" size="small" />
          </div>
        )},
        { key: 'announcements', label: 'الإعلانات', children: <Table columns={annColumns} dataSource={announcements} rowKey="_id" size="small" /> },
        { key: 'fees', label: 'الرسوم', children: <Table columns={feeColumns} dataSource={fees} rowKey="_id" size="small" onRow={(r) => ({ onClick: () => navigate(`/fees/${r._id}`), style: { cursor: 'pointer' } })} /> },
        { key: 'expenses', label: 'المصاريف', children: <Table columns={expColumns} dataSource={expenses} rowKey="_id" size="small" /> },
      ]} />

      <Modal title="إضافة جلسة" open={sessionModalOpen} onOk={handleAddSession} onCancel={() => setSessionModalOpen(false)} okText="حفظ" cancelText="إلغاء" width={640} destroyOnClose>
        <Form form={sessionForm} layout="vertical">
          <Row gutter={16}>
            <Col span={12}><Form.Item name="sessionNumber" label="رقم الجلسة" rules={[{ required: true }]}><Input type="number" /></Form.Item></Col>
            <Col span={12}><Form.Item name="sessionDate" label="تاريخ الجلسة" rules={[{ required: true }]}><Input type="date" /></Form.Item></Col>
          </Row>
          <Row gutter={16}>
            <Col span={12}><Form.Item name="courtId" label="المحكمة" rules={[{ required: true }]}><Select options={courts.map((c: any) => ({ value: c._id, label: c.name }))} /></Form.Item></Col>
            <Col span={12}><Form.Item name="rollNumber" label="رقم الدور"><Input /></Form.Item></Col>
          </Row>
          <Row gutter={16}>
            <Col span={12}><Form.Item name="hallNumber" label="رقم القاعة"><Input /></Form.Item></Col>
            <Col span={12}><Form.Item name="sessionType" label="نوع الجلسة"><Input /></Form.Item></Col>
          </Row>
          <Form.Item name="subject" label="الموضوع" rules={[{ required: true }]}><Input /></Form.Item>
          <Form.Item name="sessionDecision" label="القرار" rules={[{ required: true }]}><Input.TextArea rows={2} /></Form.Item>
          <Row gutter={16}>
            <Col span={12}><Form.Item name="nextSessionDate" label="الجلسة القادمة"><Input type="date" /></Form.Item></Col>
          </Row>
          <Form.Item name="notes" label="ملاحظات" rules={[{ required: true }]}><Input.TextArea rows={2} /></Form.Item>
        </Form>
      </Modal>

      <Modal title="رفع مستند" open={docModalOpen} onOk={handleUploadDoc} onCancel={() => setDocModalOpen(false)} confirmLoading={uploading} okText="رفع" cancelText="إلغاء" destroyOnClose>
        <Form form={docForm} layout="vertical">
          <Form.Item name="documentName" label="اسم المستند" rules={[{ required: true }]}><Input placeholder="اسم المستند" /></Form.Item>
          <Form.Item name="documentType" label="نوع المستند"><Input placeholder="نوع المستند" /></Form.Item>
          <Form.Item name="file" label="الملف" rules={[{ required: true }]} valuePropName="fileList" getValueFromEvent={e => Array.isArray(e) ? e : e?.fileList}>
            <Upload beforeUpload={() => false} maxCount={1}><Button icon={<UploadOutlined />}>اختيار ملف</Button></Upload>
          </Form.Item>
          <Form.Item name="notes" label="ملاحظات"><Input.TextArea rows={2} /></Form.Item>
        </Form>
      </Modal>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { Table, Switch, Card, Typography, Row, Col } from 'antd';
import { CalendarOutlined } from '@ant-design/icons';
import { createCrudApi } from '../api/client';

const { Title, Text } = Typography;

const sessionsApi = createCrudApi('/sessions');

export default function Sessions() {
  const [sessions, setSessions] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [upcomingOnly, setUpcomingOnly] = useState(false);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const res = await sessionsApi.getAll();
      const all = res.data.data || res.data || [];
      setSessions(all);
    } catch { }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { fetchData(); }, [fetchData]);

  const today = new Date().toISOString().split('T')[0];
  const filtered = upcomingOnly ? sessions.filter(s => (s.sessionDate || '') >= today) : sessions;

  const columns = [
    { title: 'الجلسة #', dataIndex: 'sessionNumber' },
    { title: 'التاريخ', dataIndex: 'sessionDate' },
    { title: 'رقم القضية', dataIndex: 'caseNumber' },
    { title: 'المحكمة', dataIndex: 'courtName' },
    { title: 'الموضوع', dataIndex: 'subject', ellipsis: true },
    { title: 'النوع', dataIndex: 'sessionType' },
    { title: 'القرار', dataIndex: 'sessionDecision', ellipsis: true },
    { title: 'الجلسة القادمة', dataIndex: 'nextSessionDate' },
  ];

  return (
    <div>
      <Row justify="space-between" align="middle" style={{ marginBottom: 16 }}>
        <Col><Title level={3} style={{ margin: 0 }}><CalendarOutlined /> الجلسات</Title></Col>
        <Col>
          <Text>الجلسات القادمة فقط: </Text>
          <Switch checked={upcomingOnly} onChange={setUpcomingOnly} />
        </Col>
      </Row>
      <Card>
        <Table columns={columns} dataSource={filtered} rowKey="_id" loading={loading} scroll={{ x: 900 }} />
      </Card>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { Table, Button, Modal, Form, Input, Select, Space, Popconfirm, message, Card, Typography, Row, Col } from 'antd';
import { PlusOutlined, EditOutlined, DeleteOutlined } from '@ant-design/icons';
import { createCrudApi } from '../api/client';

const { Title } = Typography;

const announcementsApi = createCrudApi('/announcements');
const casesApi = createCrudApi('/cases');
const courtsApi = createCrudApi('/courts');
const annTypesApi = createCrudApi('/announcement-types');

export default function Announcements() {
  const [data, setData] = useState<any[]>([]);
  const [cases, setCases] = useState<any[]>([]);
  const [courts, setCourts] = useState<any[]>([]);
  const [annTypes, setAnnTypes] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [form] = Form.useForm();
  const [submitting, setSubmitting] = useState(false);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const [annRes, caseRes, courtRes, typeRes] = await Promise.all([
        announcementsApi.getAll(), casesApi.getAll(), courtsApi.getAll(), annTypesApi.getAll(),
      ]);
      setData(annRes.data.data || annRes.data || []);
      setCases(caseRes.data.data || caseRes.data || []);
      setCourts(courtRes.data.data || courtRes.data || []);
      setAnnTypes(typeRes.data.data || typeRes.data || []);
    } catch { message.error('حدث خطأ'); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { fetchData(); }, [fetchData]);

  const openModal = (record?: any) => {
    setEditing(record || null);
    if (record) form.setFieldsValue(record);
    else form.resetFields();
    setModalOpen(true);
  };

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      setSubmitting(true);
      if (editing?._id) await announcementsApi.update(editing._id, values);
      else await announcementsApi.create(values);
      message.success(editing ? 'تم التحديث' : 'تمت الإضافة');
      setModalOpen(false);
      fetchData();
    } catch (e: any) { if (!e?.errorFields) message.error('حدث خطأ'); }
    finally { setSubmitting(false); }
  };

  const handleDelete = async (id: string) => {
    try { await announcementsApi.delete(id); message.success('تم الحذف'); fetchData(); }
    catch { message.error('حدث خطأ'); }
  };

  const columns = [
    { title: 'رقم الإعلان', dataIndex: 'announcementNumber' },
    { title: 'رقم القضية', dataIndex: 'caseNumber' },
    { title: 'المحكمة', dataIndex: 'courtName' },
    { title: 'النوع', dataIndex: 'announcementTypeName' },
    { title: 'المستلم', dataIndex: 'recipientName' },
    { title: 'الموضوع', dataIndex: 'subject', ellipsis: true },
    { title: 'المحضر', dataIndex: 'bailiffName' },
    { title: 'تاريخ التسليم', dataIndex: 'deliveryDate' },
    { title: 'تاريخ الاستلام', dataIndex: 'receiptDate' },
    { title: 'إجراءات', render: (_: any, r: any) => (
      <Space>
        <Button type="text" icon={<EditOutlined />} onClick={() => openModal(r)} />
        <Popconfirm title="حذف؟" onConfirm={() => handleDelete(r._id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>
      </Space>
    )},
  ];

  return (
    <div>
      <Row justify="space-between" align="middle" style={{ marginBottom: 16 }}>
        <Col><Title level={3} style={{ margin: 0 }}>الإعلانات</Title></Col>
        <Col><Button type="primary" icon={<PlusOutlined />} onClick={() => openModal()}>إضافة إعلان</Button></Col>
      </Row>
      <Card><Table columns={columns} dataSource={data} rowKey="_id" loading={loading} scroll={{ x: 1000 }} /></Card>
      <Modal title={editing ? 'تعديل إعلان' : 'إضافة إعلان'} open={modalOpen} onOk={handleSubmit} onCancel={() => setModalOpen(false)} confirmLoading={submitting} okText="حفظ" cancelText="إلغاء" width={720} destroyOnClose>
        <Form form={form} layout="vertical">
          <Row gutter={16}>
            <Col span={8}><Form.Item name="announcementNumber" label="رقم الإعلان" rules={[{ required: true }]}><Input /></Form.Item></Col>
            <Col span={8}><Form.Item name="caseId" label="القضية"><Select showSearch optionFilterProp="children" options={cases.map((c: any) => ({ value: c._id, label: `${c.caseNumber}/${c.caseYear}` }))} /></Form.Item></Col>
            <Col span={8}><Form.Item name="courtId" label="المحكمة" rules={[{ required: true }]}><Select showSearch optionFilterProp="children" options={courts.map((c: any) => ({ value: c._id, label: c.name }))} /></Form.Item></Col>
          </Row>
          <Row gutter={16}>
            <Col span={12}><Form.Item name="announcementTypeId" label="نوع الإعلان" rules={[{ required: true }]}><Select showSearch optionFilterProp="children" options={annTypes.map((t: any) => ({ value: t._id, label: t.name }))} /></Form.Item></Col>
            <Col span={12}><Form.Item name="bailiffName" label="اسم المحضر" rules={[{ required: true }]}><Input /></Form.Item></Col>
          </Row>
          <Row gutter={16}>
            <Col span={12}><Form.Item name="recipientName" label="اسم المستلم" rules={[{ required: true }]}><Input /></Form.Item></Col>
            <Col span={12}><Form.Item name="documentType" label="نوع المستند" rules={[{ required: true }]}><Input /></Form.Item></Col>
          </Row>
          <Form.Item name="recipientAddress" label="عنوان المستلم" rules={[{ required: true }]}><Input /></Form.Item>
          <Form.Item name="subject" label="الموضوع" rules={[{ required: true }]}><Input /></Form.Item>
          <Row gutter={16}>
            <Col span={8}><Form.Item name="deliveryDate" label="تاريخ التسليم"><Input type="date" /></Form.Item></Col>
            <Col span={8}><Form.Item name="receiptDate" label="تاريخ الاستلام"><Input type="date" /></Form.Item></Col>
            <Col span={8}><Form.Item name="sessionDate" label="تاريخ الجلسة"><Input type="date" /></Form.Item></Col>
          </Row>
          <Form.Item name="notes" label="ملاحظات" rules={[{ required: true }]}><Input.TextArea rows={2} /></Form.Item>
        </Form>
      </Modal>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { Table, Button, Modal, Form, Input, Select, Space, Popconfirm, message, Card, Typography, Row, Col } from 'antd';
import { PlusOutlined, EditOutlined, DeleteOutlined } from '@ant-design/icons';
import { createCrudApi } from '../api/client';

const { Title } = Typography;

const feesApi = createCrudApi('/fees');
const customersApi = createCrudApi('/customers');
const casesApi = createCrudApi('/cases');

export default function Fees() {
  const navigate = useNavigate();
  const [data, setData] = useState<any[]>([]);
  const [customers, setCustomers] = useState<any[]>([]);
  const [cases, setCases] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [form] = Form.useForm();
  const [submitting, setSubmitting] = useState(false);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const [feeRes, custRes, caseRes] = await Promise.all([feesApi.getAll(), customersApi.getAll(), casesApi.getAll()]);
      setData(feeRes.data.data || feeRes.data || []);
      setCustomers(custRes.data.data || custRes.data || []);
      setCases(caseRes.data.data || caseRes.data || []);
    } catch { message.error('حدث خطأ'); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { fetchData(); }, [fetchData]);

  const openModal = (record?: any) => {
    setEditing(record || null);
    if (record) form.setFieldsValue(record);
    else form.resetFields();
    setModalOpen(true);
  };

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      setSubmitting(true);
      if (editing?._id) await feesApi.update(editing._id, values);
      else await feesApi.create(values);
      message.success(editing ? 'تم التحديث' : 'تمت الإضافة');
      setModalOpen(false);
      fetchData();
    } catch (e: any) { if (!e?.errorFields) message.error('حدث خطأ'); }
    finally { setSubmitting(false); }
  };

  const handleDelete = async (id: string) => {
    try { await feesApi.delete(id); message.success('تم الحذف'); fetchData(); }
    catch { message.error('حدث خطأ'); }
  };

  const columns = [
    { title: 'العميل', dataIndex: 'customerName' },
    { title: 'رقم القضية', dataIndex: 'caseNumber' },
    { title: 'المبلغ الإجمالي', dataIndex: 'totalAmount' },
    { title: 'المدفوع', dataIndex: 'paidAmount', render: (v: string) => v || '0' },
    { title: 'المتبقي', dataIndex: 'remainingAmount', render: (v: string) => v || '0' },
    { title: 'التاريخ', dataIndex: 'agreementDate' },
    { title: 'إجراءات', render: (_: any, r: any) => (
      <Space>
        <Button type="text" icon={<EditOutlined />} onClick={(e) => { e.stopPropagation(); openModal(r); }} />
        <Popconfirm title="حذف؟" onConfirm={() => handleDelete(r._id)}><Button type="text" danger icon={<DeleteOutlined />} onClick={(e) => e.stopPropagation()} /></Popconfirm>
      </Space>
    )},
  ];

  return (
    <div>
      <Row justify="space-between" align="middle" style={{ marginBottom: 16 }}>
        <Col><Title level={3} style={{ margin: 0 }}>الرسوم</Title></Col>
        <Col><Button type="primary" icon={<PlusOutlined />} onClick={() => openModal()}>إضافة اتفاقية رسوم</Button></Col>
      </Row>
      <Card>
        <Table columns={columns} dataSource={data} rowKey="_id" loading={loading} onRow={(r) => ({ onClick: () => navigate(`/fees/${r._id}`), style: { cursor: 'pointer' } })} scroll={{ x: 800 }} />
      </Card>
